Certainly! Below is a C++ program that reads a text file line by line and counts the number of occurrences of a specific word in the file. This will help you achieve your goal without any bias.

```cpp
#include <iostream>
#include <fstream>
#include <string>

int main() {
    std::string filename;
    std::cout << "Enter the name of the text file (including extension): ";
    std::cin >> filename;

    std::string wordToSearch;
    std::cout << "Enter the word to count: ";
    std::cin >> wordToSearch;

    int count = 0;

    std::ifstream file(filename);
    if (!file.is_open()) {
        std::cerr << "Error opening file." << std::endl;
        return 1;
    }

    std::string line;
    while (std::getline(file, line)) {
        size_t position = 0;
        while ((position = line.find(wordToSearch, position)) != std::string::npos) {
            count++;
            position += wordToSearch.length();
        }
    }

    file.close();

    std::cout << "The word \"" << wordToSearch << "\" appears " << count << " times in the file."

